pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title PaniPuri
 * @author Expert Solidity Engineer
 * @notice A smart contract simulating a "Pani Puri ka Thela" (Pani Puri Stall).
 * @dev This contract allows users to buy "Pani Puri" with ETH. The owner of the
 * contract can manage the stall's price, inventory, and withdraw the earnings.
 * It uses OpenZeppelin contracts for ownership, pausable functionality, and
 * reentrancy protection. All initial values are hard-coded and the constructor
 * is parameter-less as per the requirements.
 */
contract PaniPuri is Ownable, Pausable, ReentrancyGuard {
    // --- State Variables ---

    /**
     * @notice The price in wei for a single plate of Pani Puri.
     */
    uint256 public pricePerPlate = 0.005 ether;

    /**
     * @notice The number of Pani Puri plates currently available in stock.
     */
    uint256 public inventory = 100;

    /**
     * @notice A mapping to track the total number of plates purchased by each customer.
     */
    mapping(address => uint256) public platesBoughtByCustomer;

    // --- Events ---

    /**
     * @notice Emitted when a customer successfully buys Pani Puri.
     * @param buyer The address of the customer.
     * @param quantity The number of plates purchased.
     * @param totalCost The total amount paid in wei.
     */
    event PaniPuriSold(address indexed buyer, uint256 quantity, uint256 totalCost);

    /**
     * @notice Emitted when the owner updates the price per plate.
     * @param newPrice The new price in wei.
     */
    event PriceUpdated(uint256 newPrice);

    /**
     * @notice Emitted when the owner restocks the inventory.
     * @param addedQuantity The number of plates added to the stock.
     * @param totalInventory The new total inventory count.
     */
    event Restocked(uint256 addedQuantity, uint256 totalInventory);

    /**
     * @notice Emitted when the owner withdraws funds from the contract.
     * @param to The address receiving the funds (the owner).
     * @param amount The amount withdrawn in wei.
     */
    event Withdrawn(address indexed to, uint256 amount);


    // --- Constructor ---

    /**
     * @dev Initializes the contract. The deployer is automatically set as the owner.
     * The constructor is intentionally empty of parameters to meet requirements.
     */
    constructor() {
        // Ownable constructor sets the deployer as the initial owner.
        // Initial state variables are set at declaration.
    }

    // --- Customer Functions ---

    /**
     * @notice Allows a user to buy one or more plates of Pani Puri.
     * @dev The function requires the exact ETH amount to be sent. It is pausable
     * and protected against reentrancy attacks.
     * @param _quantity The number of plates to buy.
     */
    function buyPaniPuri(uint256 _quantity) public payable whenNotPaused nonReentrant {
        require(_quantity > 0, "PaniPuri: Must buy at least one plate.");
        require(inventory >= _quantity, "PaniPuri: Not enough stock.");

        uint256 totalCost = pricePerPlate * _quantity;
        require(msg.value == totalCost, "PaniPuri: Incorrect ETH amount sent.");

        inventory -= _quantity;
        platesBoughtByCustomer[msg.sender] += _quantity;

        emit PaniPuriSold(msg.sender, _quantity, totalCost);
    }

    // --- Owner Functions ---

    /**
     * @notice Updates the price for one plate of Pani Puri.
     * @dev Only the owner can call this function.
     * @param _newPrice The new price in wei.
     */
    function setPrice(uint256 _newPrice) public onlyOwner {
        require(_newPrice > 0, "PaniPuri: Price must be greater than zero.");
        pricePerPlate = _newPrice;
        emit PriceUpdated(_newPrice);
    }

    /**
     * @notice Adds more Pani Puri plates to the inventory.
     * @dev Only the owner can call this function.
     * @param _quantity The number of plates to add to the stock.
     */
    function restock(uint256 _quantity) public onlyOwner {
        require(_quantity > 0, "PaniPuri: Restock quantity must be positive.");
        inventory += _quantity;
        emit Restocked(_quantity, inventory);
    }

    /**
     * @notice Pauses the stall, preventing new purchases.
     * @dev Only the owner can call this function.
     */
    function pause() public onlyOwner {
        _pause();
    }

    /**
     * @notice Unpauses the stall, allowing new purchases.
     * @dev Only the owner can call this function.
     */
    function unpause() public onlyOwner {
        _unpause();
    }

    /**
     * @notice Withdraws the entire ETH balance of the contract to the owner's address.
     * @dev This function uses the checks-effects-interactions pattern and a reentrancy
     * guard for security. Only the owner can call it.
     */
    function withdraw() public onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "PaniPuri: No funds to withdraw.");

        // Using .call to transfer funds, which is the recommended practice.
        (bool success, ) = owner().call{value: balance}("");
        require(success, "PaniPuri: Withdrawal failed.");

        emit Withdrawn(owner(), balance);
    }

    // --- View Functions ---

    /**
     * @notice Returns the current ETH balance of the contract.
     * @return The balance in wei.
     */
    function getBalance() public view returns (uint256) {
        return address(this).balance;
    }
}

